function ref(s: string, table: u8[]): u8[] {
    let out: u8[] = [];
    let i: i32 = 0;
    while (i < s.len()) {
        let c: i32 = s[i] as i32;
        if (c < table.len()) { c = table[c] as i32; }
        out = out.append(c as u8);
        i = i + 1;
    }
    return out;
}
function ref_filtered(s: string, drop: u8[]): u8[] {
    let out: u8[] = [];
    let i: i32 = 0;
    while (i < s.len()) {
        let c: i32 = s[i] as i32;
        if (c >= drop.len() || drop[c] as i32 == 0) { out = out.append(c as u8); }
        i = i + 1;
    }
    return out;
}
function alternate_table(): u8[] {
    let t: u8[] = __alloc_u8(256);
    let z: i32 = 0;
    while (z < 256) { t = t.with(z, (z % 2) as u8); z = z + 1; }
    return t;
}
function check_filtered(b: usize, held: string, s: string, drop: u8[]): boolean {
    buf_push(b, held);
    buf_push_filtered(b, s, drop);
    return same_bytes(buf_take_bytes(b), held, ref_filtered(s, drop));
}
function ref_expanded(s: string, t: u8[]): u8[] {
    let out: u8[] = [];
    let i: i32 = 0;
    while (i < s.len()) {
        let c: i32 = s[i] as i32;
        if (c * 8 + 8 > t.len()) {
            out = out.append(c as u8);
        } else {
            let n: i32 = t[c * 8] as i32;
            if (n > 7) { n = 7; }
            let k: i32 = 0;
            while (k < n) { out = out.append(t[c * 8 + 1 + k]); k = k + 1; }
        }
        i = i + 1;
    }
    return out;
}
// Byte c becomes c % 8 copies of 'a' + c % 26; every fifth record claims a
// length past seven, which counts as seven.
function expand_table(): u8[] {
    let t: u8[] = __alloc_u8(2048);
    let c: i32 = 0;
    while (c < 256) {
        let n: i32 = c % 8;
        if (c % 5 == 0) { n = 9 + c % 100; }
        t = t.with(c * 8, n as u8);
        let k: i32 = 1;
        while (k < 8) { t = t.with(c * 8 + k, (97 + c % 26) as u8); k = k + 1; }
        c = c + 1;
    }
    return t;
}
function check_expanded(b: usize, held: string, s: string, t: u8[]): boolean {
    buf_push(b, held);
    buf_push_expanded(b, s, t);
    return same_bytes(buf_take_bytes(b), held, ref_expanded(s, t));
}
function rot_table(): u8[] {
    let t: u8[] = __alloc_u8(256);
    let z: i32 = 0;
    while (z < 256) { t = t.with(z, ((z + 13) % 256) as u8); z = z + 1; }
    return t;
}
function check(b: usize, held: string, s: string, table: u8[]): boolean {
    buf_push(b, held);
    buf_push_mapped(b, s, table);
    return same_bytes(buf_take_bytes(b), held, ref(s, table));
}
function check_bytes(b: usize, src: u8[], table: u8[]): boolean {
    buf_push_bytes_mapped(b, src, table);
    let out: u8[] = buf_take_bytes(b);
    if (out.len() != src.len()) { return false; }
    let i: i32 = 0;
    while (i < src.len()) { if (out[i] != table[src[i] as i32]) { return false; } i = i + 1; }
    return true;
}
function same_bytes(actual: u8[], held: string, tail: u8[]): boolean {
    if (actual.len() != held.len() + tail.len()) { return false; }
    let i: i32 = 0;
    while (i < held.len()) { if (actual[i] != held[i]) { return false; } i = i + 1; }
    let j: i32 = 0;
    while (j < tail.len()) { if (actual[i + j] != tail[j]) { return false; } j = j + 1; }
    return true;
}
function main(): i32 {
    let b: usize = buf_new(4);
    let rot: u8[] = rot_table();
    let short: u8[] = [120 as u8, 121 as u8, 122 as u8];
    let none: u8[] = [];
    let alt: u8[] = alternate_table();
    let ex: u8[] = expand_table();
    let n: i32 = 0;
    let s: string = "";
    while (n <= 40) {
        if (!check(b, "", s, rot)) { return 1; }
        if (!check(b, "ab", s, short)) { return 2; }
        if (!check(b, "", s, none)) { return 3; }
        if (!check_filtered(b, "", s, alt)) { return 7; }
        if (!check_filtered(b, "cd", s, short)) { return 8; }
        if (!check_filtered(b, "", s, none)) { return 9; }
        if (!check_filtered(b, "", s, rot)) { return 10; }
        if (!check_expanded(b, "ef", s, ex)) { return 12; }
        if (!check_expanded(b, "", s, short)) { return 13; }
        s = s + string_from_bytes_unchecked([((n * 7 + 1) % 128) as u8]);
        n = n + 1;
    }
    if (!check(b, "held", "\x00\x01\x02\x03", short)) { return 4; }
    if (!check(b, "", "\x00\x01\x02\x03", short) || buf_len(b) != 0) { return 5; }
    let big: string = "";
    let k: i32 = 0;
    while (k < 300) { big = big + "9z"; k = k + 1; }
    if (!check(b, "", big, rot)) { return 6; }
    if (!check_filtered(b, "", big, alt)) { return 11; }
    if (!check_expanded(b, "", big, ex)) { return 14; }
    let every: string = "";
    k = 0;
    while (k < 384) { every = every + string_from_bytes_unchecked([(k % 128) as u8]); k = k + 1; }
    if (!check_expanded(b, "gh", every, ex)) { return 15; }
    let scram: u8[] = __alloc_u8(256);
    k = 0;
    while (k < 256) { scram = scram.with(k, ((k * 167 + 29) % 256) as u8); k = k + 1; }
    let src: u8[] = [];
    k = 0;
    while (k <= 300) {
        if (!check_bytes(b, src, scram)) { return 16; }
        if (!check(b, "", string_from_bytes_unchecked(src), scram)) { return 17; }
        src = src.append(((k * 131 + 7) % 256) as u8);
        k = k + 1;
    }
    buf_free(b);
    return 42;
}

